{
  "schemaVersion": 1,
  "task": 45,
  "domain": "D17",
  "title": "협상·거래·강화·계약",
  "status": "approved-structural-contract-with-explicit-proposal-inputs",
  "rulesVersion": "SP-1.0.0 plus sealed Task26 selections 2026-10-08",
  "authority": {
    "canonicalAnchors": [
      "sp1.b11-sp1.b14",
      "sp1.b24-sp1.b35",
      "sp1.b61-sp1.b67",
      "sp1.b82-sp1.b90",
      "sp1.b93",
      "sp1.b117-sp1.b128",
      "rules-factions-warfare-clauses.json#war-score-owner.20261003.rules",
      "rules-factions-warfare-clauses.json#sp1.20261003.peace-extension"
    ],
    "sealedSelections": [
      {
        "row": "D06",
        "decisionId": "GP-13",
        "chosenOption": "A",
        "application": "Treaty indivisible clauses, legal-effect events, and physical-handoff events are distinct. Concrete CB, truce, reparation, captive, and superior-contract entries remain authored inputs rather than invented defaults."
      },
      {
        "row": "D12",
        "decisionId": "T68-D17-PRICE-ACCEPTANCE",
        "chosenOption": "A",
        "application": "Asset value, action cost, and actor-specific acceptance are separate. A missing registered price blocks final signature; V<=W is never automatic consent. Relevant state changes require explicit reevaluation on a new snapshot and invalidate old acceptance."
      },
      {
        "row": "D17",
        "decisionId": "GP-07",
        "chosenOption": "B",
        "application": "Unassigned title and superior-contract records may be authored as proposals for item-by-item approval. The mechanism may validate supplied ratification records but cannot create holders, periods, or procedures."
      },
      {
        "row": "D19",
        "decisionId": "T68-D11-CONTRACT-RECALL",
        "chosenOption": "A",
        "application": "Each contract supplies authority, duration, duties, breach, ratification, expiry/death, conflict, and physical handoff clauses. No unconditional recall or automatic return is inferred."
      },
      {
        "row": "D22",
        "decisionId": "T68-NUMERIC-DESIGN-ASSUMPTIONS",
        "chosenOption": "B",
        "application": "Common units are explicit before formula coefficients. D17 accepts exact integer price-unit inputs only; coefficients and tables remain separately approved versioned inputs."
      }
    ],
    "selectionRule": "All 37 decision rows were read through their consequences. D06, D12, D17, D19, and D22 directly constrain D17. Every other row is recorded in proposals.json as deferred-with-trace rather than called irrelevant.",
    "researchLimit": "Prior CK3/Norland D17 dossiers and the 2026-10-06 D17 proposal sheet are comparison evidence, not Seoul numeric authority. No external price, acceptance threshold, term duration, reservation priority, or breach coefficient is adopted.",
    "gurpsLike": {
      "basis": "task-25-gurps-like-basis-20261008/basis.json",
      "workedChecks": "task-25-gurps-like-basis-20261008/worked-checks.json",
      "D17NumericApplicability": "none",
      "reason": "Negotiation consent and legal feasibility are not reaction rolls or quick contests. The public Lite reaction structure explicitly does not force contractual consent. D17 uses no 3d6, CP, skill, damage, or derived-character formula."
    }
  },
  "mechanisms": [
    {
      "id": "ELIGIBILITY",
      "approved": true,
      "algorithm": "Below the D16 endpoint, an authorized actor may submit itemized demands/offers. Finalization requires distinct signer/disposer authority, stable subject and beneficiary IDs, no unauthorized third-party right, explicit required consent, actual feasibility, and one pledge per subject within the proposal."
    },
    {
      "id": "VALUATION",
      "approved": true,
      "algorithm": "Every final term carries a registered price record with version, snapshot digest, exact integer amount, and one common price unit. V=sum(demands)-sum(offers). Missing or stale price makes valuation unresolved and blocks acceptance/signature; it is never free."
    },
    {
      "id": "RESPONSE",
      "approved": true,
      "algorithm": "Acceptance is an explicit receipt by an authorized party bound to proposal revision and snapshot digest. Rejection and counteroffer are explicit branches. V<=W, positive reaction, high trust, or favorable relationship never creates consent."
    },
    {
      "id": "REPRICE",
      "approved": true,
      "algorithm": "A relevant state change preserves proposal identity only through an explicit reprice event that creates a new revision/snapshot, invalidates all old acceptance receipts, revalidates terms, and requires renewed acceptance before signature."
    },
    {
      "id": "ENDPOINT",
      "approved": true,
      "algorithm": "If D16 supplies |W|=100 before signature, discard the open proposal and consume only the valid casus-belli endpoint result. Out-of-goal terms, third-party rights, and voluntary extras are not forced. Same-boundary priority remains D18 input rather than a D17 invention."
    },
    {
      "id": "SIGN",
      "approved": true,
      "algorithm": "On a valid accepted snapshot, atomically verify and acquire supplied reservations, emit exactly one settlement ID, apply supplied legal effects, and create per-term delivery obligations. Signature does not teleport or duplicate property or people."
    },
    {
      "id": "DELIVERY",
      "approved": true,
      "algorithm": "Delivery advances exact delivered and remaining quantities under custody/route facts. Partial completion survives interruption, death, cancellation, and breach. Only remaining obligation is revalidated; remedy and timing require supplied contract clauses."
    },
    {
      "id": "IDEMPOTENCY",
      "approved": true,
      "algorithm": "A repeated event ID with the same canonical payload returns its stored receipt; a different payload under the same ID is rejected. A completed settlement/result ID is never applied twice."
    }
  ],
  "unverifiedStructuralScope": [
    {
      "id": "U-REJECT",
      "status": "UNVERIFIED",
      "detail": "A first-class reject transition, rejection receipt payload, and persistence/replay semantics are described by SP1 but are not executed by validator.mjs."
    },
    {
      "id": "U-COUNTEROFFER",
      "status": "UNVERIFIED",
      "detail": "Counteroffer identity, parent proposal linkage, term replacement rules, and acceptance invalidation are not executed."
    },
    {
      "id": "U-CANCEL",
      "status": "UNVERIFIED",
      "detail": "Open-proposal and signed-contract cancellation authority, reservation release, and remaining-obligation handling are not executed."
    },
    {
      "id": "U-DEATH",
      "status": "UNVERIFIED",
      "detail": "Signer death and authority-loss event ingestion, per-contract revalidation, and preservation of completed delivery are specified but not executed as a transition."
    },
    {
      "id": "U-EXPIRY",
      "status": "UNVERIFIED",
      "detail": "Deadline/invalidator-driven expiry and reservation release are not executed because actual expiry inputs remain proposals."
    },
    {
      "id": "U-FORGERY",
      "status": "UNVERIFIED",
      "detail": "Forged signatures, forged authority evidence, and cryptographic/authenticity proof are not modeled beyond stable event/payload collision checks."
    },
    {
      "id": "U-REPRICE-ITEM-REVALIDATION",
      "status": "UNVERIFIED",
      "detail": "Reprice executes new revision/snapshot and acceptance invalidation, but it does not rerun item authority, third-party rights, consent, feasibility, or reservation validation until a later accept/sign event."
    }
  ],
  "scope": {
    "evidenceOnly": true,
    "productEdited": false,
    "canonAdopted": false,
    "runtimeImplemented": false,
    "fullNumericDomainClosure": false,
    "proposalPolicy": "Fixture prices, quantities, IDs, deadlines, authorities, and remedies are illustrative oracle data only, not approved Seoul values or world records.",
    "integrationDeferral": "Canonical GDD mechanism-d17.json, collection registration, rendered lock, materialization, product verify --domain D17, and commits belong to the separate later integration wave."
  },
  "sourceEvidenceStatus": "approved-structural-contract-with-explicit-proposal-inputs",
  "decisionDisposition": [
    {
      "row": "D01",
      "decisionId": "GP-01",
      "disposition": "defer-with-trace",
      "reason": "Opening-candidate detention/location records may affect a person term, but D17 consumes supplied current status only."
    },
    {
      "row": "D02",
      "decisionId": "GP-02",
      "disposition": "defer-with-trace",
      "reason": "Route observation and replan state may affect delivery feasibility; D06 owns it."
    },
    {
      "row": "D03",
      "decisionId": "GP-04",
      "disposition": "defer-with-trace",
      "reason": "Ration/wage performance may become a contract term; D04/D02 own quantities and effects."
    },
    {
      "row": "D04",
      "decisionId": "GP-05",
      "disposition": "defer-with-trace",
      "reason": "Recipe resources and work stages may be exchanged, but D05 owns production values."
    },
    {
      "row": "D05",
      "decisionId": "GP-10",
      "disposition": "defer-with-trace",
      "reason": "Knowledge access can be a term; D14 owns requirements and progress."
    },
    {
      "row": "D06",
      "decisionId": "GP-13",
      "disposition": "applied",
      "reason": "Directly governs treaties, truce, reparations, captives, rights, legal effect, and physical handoff."
    },
    {
      "row": "D07",
      "decisionId": "T68-D01-ISSUANCE",
      "disposition": "defer-with-trace",
      "reason": "Person issuance ledger can identify parties; D01 owns individual approval."
    },
    {
      "row": "D08",
      "decisionId": "T68-D07-EVALUATION-DECAY",
      "disposition": "defer-with-trace",
      "reason": "Late reports and evaluation lifecycle may inform response, but no D17 acceptance coefficient is inferred."
    },
    {
      "row": "D09",
      "decisionId": "T68-D09-COUNTRY-LAWS",
      "disposition": "defer-with-trace",
      "reason": "Country quorum/resolver/ratification records are upstream authority facts consumed when supplied."
    },
    {
      "row": "D10",
      "decisionId": "T68-D12-PERMANENT-DETENTION",
      "disposition": "defer-with-trace",
      "reason": "Detention and return facts affect person terms; D12 owns control transitions."
    },
    {
      "row": "D11",
      "decisionId": "T68-D16-ORGANIZATION-LIFECYCLE",
      "disposition": "defer-with-trace",
      "reason": "Organization survival and representative authority are upstream D16 facts."
    },
    {
      "row": "D12",
      "decisionId": "T68-D17-PRICE-ACCEPTANCE",
      "disposition": "applied",
      "reason": "Direct D17 price, acceptance, snapshot, reprice, and renewed-consent boundary."
    },
    {
      "row": "D13",
      "decisionId": "T68-PF-03",
      "disposition": "defer-with-trace",
      "reason": "Cast field corrections do not authorize negotiation values or parties."
    },
    {
      "row": "D14",
      "decisionId": "T68-PF-05",
      "disposition": "defer-with-trace",
      "reason": "Identity mapping approval is separate from payload approval; D17 never treats mapping as current authority."
    },
    {
      "row": "D15",
      "decisionId": "T68-PF-06",
      "disposition": "defer-with-trace",
      "reason": "Unit type mapping and instance issuance are D15 inputs, not D17 terms by default."
    },
    {
      "row": "D16",
      "decisionId": "T68-PF-07",
      "disposition": "defer-with-trace",
      "reason": "Population token identity may underlie labor terms; D04 owns conservation."
    },
    {
      "row": "D17",
      "decisionId": "GP-07",
      "disposition": "applied",
      "reason": "Title and superior-contract proposal authoring and ratification boundaries affect D17 terms directly."
    },
    {
      "row": "D18",
      "decisionId": "GP-11",
      "disposition": "defer-with-trace",
      "reason": "Command evaluation records may affect an actor's judgment, but D17 consumes attributed facts without making a score."
    },
    {
      "row": "D19",
      "decisionId": "T68-D11-CONTRACT-RECALL",
      "disposition": "applied",
      "reason": "Direct contract authority, duration, duty, breach, ratification, conflict, death, and handoff boundary."
    },
    {
      "row": "D20",
      "decisionId": "T68-PF-01",
      "disposition": "defer-with-trace",
      "reason": "Character values are not negotiation prices or acceptance coefficients."
    },
    {
      "row": "D21",
      "decisionId": "T68-PF-02",
      "disposition": "defer-with-trace",
      "reason": "Organization values/policies require field-level approval before D17 can consume them."
    },
    {
      "row": "D22",
      "decisionId": "T68-NUMERIC-DESIGN-ASSUMPTIONS",
      "disposition": "applied",
      "reason": "D17 declares price and quantity units first; formula coefficients remain held."
    },
    {
      "row": "D23",
      "decisionId": "T68-TRAINING-SKILL-SPECIFIC",
      "disposition": "defer-with-trace",
      "reason": "Training conversion/cost is D14-owned and cannot become a D17 price automatically."
    },
    {
      "row": "D24",
      "decisionId": "T68-COMBAT-THREE-DIMENSIONS",
      "disposition": "defer-with-trace",
      "reason": "Combat aggregation/loss ledger can affect war facts, but D16 supplies the settlement snapshot."
    },
    {
      "row": "D25",
      "decisionId": "G1",
      "disposition": "defer-with-trace",
      "reason": "Pilot Spear intent and CP arithmetic have no D17 formula role."
    },
    {
      "row": "D26",
      "decisionId": "G2",
      "disposition": "defer-with-trace",
      "reason": "Skills/TL/language issuance cannot supply acceptance or price without separate approval."
    },
    {
      "row": "D27",
      "decisionId": "T68-VARIABLE-CAPACITY",
      "disposition": "defer-with-trace",
      "reason": "Capacity may constrain feasibility; D15 supplies the approved state."
    },
    {
      "row": "D28",
      "decisionId": "GP-02",
      "disposition": "defer-with-trace",
      "reason": "Movement/load facts can constrain delivery, but D06 owns conversions and route state."
    },
    {
      "row": "D29",
      "decisionId": "GP-04",
      "disposition": "defer-with-trace",
      "reason": "Health/needs/labor effects may constrain action feasibility; D02/D04 own them."
    },
    {
      "row": "D30",
      "decisionId": "GP-08",
      "disposition": "defer-with-trace",
      "reason": "Command eligibility and injury modifiers may constrain authority/feasibility; D15 owns them."
    },
    {
      "row": "D31",
      "decisionId": "GP-10",
      "disposition": "defer-with-trace",
      "reason": "Skill training definitions and rates are D14 inputs, not D17 values."
    },
    {
      "row": "D32",
      "decisionId": "GP-11",
      "disposition": "defer-with-trace",
      "reason": "Combat roll structure and realtime timing do not become negotiation acceptance mechanics."
    },
    {
      "row": "D33",
      "decisionId": "T68-D01-ISSUANCE",
      "disposition": "defer-with-trace",
      "reason": "Individual CP/abilities require person-by-person approval and are not D17 price inputs by default."
    },
    {
      "row": "D34",
      "decisionId": "T68-PF-04",
      "disposition": "defer-with-trace",
      "reason": "Corpus value reclassification is not negotiation authority."
    },
    {
      "row": "D35",
      "decisionId": "T68-PF-06",
      "disposition": "defer-with-trace",
      "reason": "Employment contract price and capability/equipment eligibility are separate D04/D15 records; D17 may consume only approved records."
    },
    {
      "row": "D36",
      "decisionId": "T68-PF-07",
      "disposition": "defer-with-trace",
      "reason": "Generated attributes/skills remain candidate data and cannot determine terms without approval."
    },
    {
      "row": "D37",
      "decisionId": "T68-NUMERIC-DESIGN-ASSUMPTIONS",
      "disposition": "defer-with-trace",
      "reason": "Health-derived one-time settlement prevents duplicated losses upstream; D17 consumes the resulting approved state only."
    }
  ],
  "proposalContext": {
    "policy": "Every held value remains a proposal and is traced to an owner-decision boundary. Every sealed row was checked through consequences; non-D17 rows are deferred-with-trace, not declared irrelevant.",
    "unverifiedScopeHolds": [
      {
        "id": "U-REJECT",
        "status": "UNVERIFIED-STRUCTURAL",
        "separateFromProposal": true,
        "detail": "Reject transition and durable receipt not executed."
      },
      {
        "id": "U-COUNTEROFFER",
        "status": "UNVERIFIED-STRUCTURAL",
        "separateFromProposal": true,
        "detail": "Counteroffer transition and lineage not executed."
      },
      {
        "id": "U-CANCEL",
        "status": "UNVERIFIED-STRUCTURAL",
        "separateFromProposal": true,
        "detail": "Cancellation and reservation-release transitions not executed."
      },
      {
        "id": "U-DEATH",
        "status": "UNVERIFIED-STRUCTURAL",
        "separateFromProposal": true,
        "detail": "Death/authority-loss revalidation transition not executed."
      },
      {
        "id": "U-EXPIRY",
        "status": "UNVERIFIED-STRUCTURAL",
        "separateFromProposal": true,
        "detail": "Expiry transition not executed."
      },
      {
        "id": "U-FORGERY",
        "status": "UNVERIFIED-STRUCTURAL",
        "separateFromProposal": true,
        "detail": "Signature/authority forgery detection not executed beyond event collision."
      },
      {
        "id": "U-REPRICE-ITEM-REVALIDATION",
        "status": "UNVERIFIED-STRUCTURAL",
        "separateFromProposal": true,
        "detail": "Reprice does not itself execute item-level authority/right/consent/feasibility revalidation."
      }
    ],
    "integrationDeferrals": [
      "Author GDD/canon/locales/ko-KR/system-design/mechanism-d17.json in the separate canonical integration wave.",
      "Register doc.Mechanism-D17 in GDD/canon/collections/system-design.json and update GDD/canon/rendered.lock.json in that same later increment.",
      "Materialize and inspect Mechanism-D17.md, then run TOOL/tools/mechanisms/verify.mjs --domain D17 against canonical cases after integration.",
      "Create the canonical docs commit only in the later integration wave; this evidence task creates no commit."
    ]
  },
  "landingDisposition": {
    "documentRegistration": "bounded canonical contract only",
    "runtimeAndNumericAdoption": false,
    "commonExecutableVerifier": "not run; executionSchemaReady:false",
    "sourceDeferrals": "historical document-registration and commit deferrals are satisfied by this landing; cross-domain/runtime/executable work remains unclaimed"
  }
}
